// Anyone can find a URL; only the key holder gets to spend API credits.
const q = $input.first().json.query || {};
if (q.k !== 'moon-2026') return [];
return [{ json: { manual: true } }];

// Everything Marcus is allowed to know this break lives on this sheet.
// Facts come from NWS, MegaSeg's own ComingUp log, AzuraCast history and
// the human-curated events board — the model only ever styles them.
const sd = $getWorkflowStaticData('global');

// --- time ---
const phx = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Phoenix' }));
const pad = (n) => String(n).padStart(2, '0');
const today = phx.getFullYear() + '-' + pad(phx.getMonth() + 1) + '-' + pad(phx.getDate());
const daysN = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const weekday = daysN[phx.getDay()];
const hour = phx.getHours();
const clock = (((hour + 11) % 12) + 1) + ':' + pad(phx.getMinutes()) + ' ' + (hour >= 12 ? 'PM' : 'AM');
const bucket = hour < 5 ? 'overnight' : hour < 7 ? 'early morning' : hour < 9 ? 'morning drive' : hour < 11 ? 'late morning' : hour < 14 ? 'midday' : hour < 17 ? 'afternoon' : hour < 19 ? 'late afternoon' : hour < 22 ? 'evening' : 'late night';

// --- weather: NWS current observation, real numbers or nothing ---
let wx = null;
try {
  const o = $('Weather for DJ2').first().json.currentobservation;
  if (o && o.Temp && o.Weather) wx = { temp: parseInt(o.Temp, 10), cond: String(o.Weather) };
} catch (e) {}
let vibe = null;
if (wx) {
  const c = wx.cond.toLowerCase();
  vibe = c.includes('rain') ? 'wet and moody' : c.includes('snow') ? 'cold and wintry'
    : wx.temp <= 40 ? 'chilly' : wx.temp <= 55 ? 'cool' : wx.temp <= 70 ? 'comfortable' : wx.temp <= 85 ? 'warm' : 'hot';
}

// --- coming up: MegaSeg's own log — accurate to the actual playout ---
const aliases = { 'Daryl Hall & John Oates': 'Hall and Oates', 'Daryl Hall and John Oates': 'Hall and Oates', 'Earth, Wind & Fire': 'Earth Wind and Fire', 'Crosby, Stills, Nash & Young': 'CSNY' };
// AzuraCast titles arrive as 'Song - Album' with (Remaster) tags; strip both to the bare song.
const cleanTitle = (t) => String(t || '').split(/\s+-\s+/)[0].replace(/\([^)]*\)/g, '').replace(/\s+/g, ' ').trim();
// News bumpers/IDs come through with a blank artist or an obvious non-music title.
const isBumper = (title, artist, duration) => {
  const t = String(title || '').toLowerCase();
  const a = String(artist || '').trim().toLowerCase().replace(/\s+/g, ' ');
  const dur = Number(duration) || 0;
  // Ads, IDs, sweepers and spots run short; real songs run 150s+. dur 0 = now-playing (unknown), keep.
  if (dur > 0 && dur < 90) return true;
  if (!a) return true;                                        // ads/news/IDs come through blank
  if (a.replace(/\s+/g, '') === 'live365') return true;       // Live365 ad injector
  if (['mellow mountain radio', 'station id', 'app announcement'].includes(a)) return true;
  // backstop for anything long-form mis-tagged with a real-looking artist
  return /adbreak|ad break|sweeper|imaging|bumper|station id|\bliner\b|\bpromo\b|\bident\b/.test(t);
};
let nowSong = null;
try {
  const npNow = ($('Ask the airwaves').first().json || {}).now_playing || {};
  const s = npNow.song || {};
  const elapsed = Number(npNow.elapsed) || 0;
  // elapsed > 90s => certainly a real song mid-play, not a short ad/ID (those never run that long).
  // duration is 0/unreliable on this station, so elapsed is the guard; artist/title ad-filters still apply.
  if (s.title && !isBumper(s.title, s.artist, 999) && elapsed > 90) {
    const t = cleanTitle(s.title);
    if (t && t.toLowerCase() !== 'mellow mountain radio') {
      nowSong = { title: t.slice(0, 120), artist: aliases[s.artist] || String(s.artist || '').slice(0, 120) };
    }
  }
} catch (e) {}

// --- recently played: AzuraCast history, past plays are always safe facts ---
const recent = [];
try {
  const np = $('Ask the airwaves').first().json || {};
  for (const r of (np.song_history || [])) {
    const s = r && r.song;
    if (!s || !s.title) continue;
    if (isBumper(s.title, s.artist, r.duration)) continue;
    const title = cleanTitle(s.title);
    if (!title || title.toLowerCase() === 'mellow mountain radio') continue;
    recent.push({ title: title.slice(0, 120), artist: aliases[s.artist] || String(s.artist || '').slice(0, 120) });
    if (recent.length >= 5) break;
  }
} catch (e) {}

// --- events: human board + live feeds from the mellowmountainradio site ---
// Two slots: a near-term local Sedona happening, and an on-brand Arizona show
// to tease. Every field is a real fetched fact; the model only styles them.
const dstr = (dt) => dt.getFullYear() + '-' + pad(dt.getMonth() + 1) + '-' + pad(dt.getDate());
const localHorizon = new Date(phx); localHorizon.setDate(localHorizon.getDate() + 21);
const showHorizon = new Date(phx); showHorizon.setDate(showHorizon.getDate() + 60);
const localH = dstr(localHorizon);
const showH = dstr(showHorizon);
const VERDE = new Set(['sedona', 'village of oak creek', 'cottonwood', 'clarkdale', 'jerome', 'camp verde', 'flagstaff']);

// GitHub raw serves .json as text/plain, so n8n leaves the body unparsed in .data.
const feed = (nodeName) => {
  try {
    const j = $(nodeName).first().json || {};
    return typeof j.data === 'string' ? JSON.parse(j.data) : j;
  } catch (e) { return {}; }
};
// local happenings: curated board (highest priority) + Community Library Sedona
sd.events = (sd.events || []).filter((e) => e && e.date >= today);
const localPool = [];
for (const e of sd.events) {
  if (e.date <= localH) localPool.push({ date: e.date, name: e.name, place: e.place || '', note: e.note || '', rank: 0 });
}
try {
  const lib = feed('Fetch library events');
  for (const e of (lib.events || [])) {
    if (!e || !e.date || e.date < today || e.date > localH) continue;
    localPool.push({ date: e.date, name: e.title, place: 'the Community Library in Sedona', note: e.time ? ('starts ' + e.time) : '', rank: 1 });
  }
} catch (e) {}
localPool.sort((a, b) => (a.rank - b.rank) || (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
// A curated/Verde-local entry (rank 0) wins outright; otherwise rotate among the soonest few for variety.
const pickFrom = (arr, n) => arr.length ? (arr[0].rank === 0 ? arr[0] : arr[Math.floor(Math.random() * Math.min(n, arr.length))]) : null;
const evLocal = pickFrom(localPool, 4);

// upcoming shows: Arizona concerts + festivals (Verde Valley first, then soonest)
const showPool = [];
try {
  const con = feed('Fetch concerts');
  for (const s of (con.concerts || [])) {
    if (!s || s.state !== 'AZ' || !s.date || s.date < today || s.date > showH) continue;
    const near = VERDE.has(String(s.city || '').toLowerCase());
    showPool.push({ date: s.date, name: (aliases[s.artist] || s.artist) + ' at ' + s.venue, place: s.city + ', Arizona', rank: near ? 0 : 1 });
  }
} catch (e) {}
try {
  const fes = feed('Fetch festivals');
  for (const f of (fes.festivals || [])) {
    const fd = f && f.start;
    if (!f || f.state !== 'AZ' || !fd || fd < today || fd > showH) continue;
    const near = VERDE.has(String(f.city || '').toLowerCase());
    showPool.push({ date: fd, name: f.name, place: f.city + ', Arizona', rank: near ? 0 : 1 });
  }
} catch (e) {}
showPool.sort((a, b) => (a.rank - b.rank) || (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
const evShow = pickFrom(showPool, 5);

// upcoming movies: Sedona Film Festival screenings (Sedona/Verde first, then soonest few)
const movieHorizon = new Date(phx); movieHorizon.setDate(movieHorizon.getDate() + 14);
const movieH = dstr(movieHorizon);
const moviePool = [];
try {
  const st = feed('Fetch showtimes');
  for (const m of (st.showings || [])) {
    if (!m || !m.date || m.date < today || m.date > movieH) continue;
    const near = VERDE.has(String(m.city || '').toLowerCase());
    moviePool.push({ date: m.date, time: m.time || '', title: m.title, venue: m.venue, place: m.city, rank: near ? 0 : 1 });
  }
} catch (e) {}
moviePool.sort((a, b) => (a.rank - b.rank) || (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
const evMovie = moviePool.length ? moviePool[Math.floor(Math.random() * Math.min(5, moviePool.length))] : null;

// ============================================================================
// THE DIRECTOR — pick a fresh angle so no two breaks feel the same.
// Each break leads with ONE subject (sometimes one light second), rotating to
// avoid the recent past. What is available + the time of day shape the odds.
// ============================================================================
const weatherMode = ['exact', 'descriptive', 'mixed'][Math.floor(Math.random() * 3)];
const mSelfID = Math.random() < 0.4;   // ~40% of breaks he says his on-air name
const nightish = (bucket === 'overnight' || bucket === 'late night' || bucket === 'early morning');
const drive = (bucket === 'morning drive' || bucket === 'afternoon' || bucket === 'late afternoon');

const siteSpotlights = [
  { name: 'Chakras & Tarot', hook: 'the full seventy-eight-card tarot with a card of the day drawn over Sedona, plus the seven chakras and their healing frequencies' },
  { name: 'Sound Healing', hook: 'the KAZM Harmonic Stack — binaural tone sessions and a coherent-breathing pacer, all synthesized live right in your browser' },
  { name: 'Astrology', hook: 'daily readings drawn from the real sky over Sedona, live planet positions, and your own Sun, Moon and Rising birth chart' },
  { name: 'Cosmic Conditions', hook: "Sedona's vortex energy and tonight's cosmic weather — the moon phase, the geomagnetic field, and the Earth's Schumann resonance" },
  { name: 'the Song Time Machine', hook: 'every song we play logged the moment it airs — look up what was on at any minute, or browse the weekly spin charts' },
  { name: "the Listeners' Lounge", hook: 'every broadcast hour of KAZM kept for two weeks and ready to replay, so you never miss a moment' },
  { name: 'the Jeep Trails guide', hook: 'every legendary Sedona trail — Broken Arrow, Soldier Pass, Schnebly Hill — with live run-verdicts and a last-safe-start clock' },
  { name: 'Events and Adventures', hook: 'live trail conditions, the Oak Creek flow, Slide Rock, the ski report, even geocaching spots to get you outside' },
  { name: 'Seen around Sedona', hook: 'a living field guide to the Verde Valley — live wildlife sightings and what is blooming right now' },
  { name: 'Contests', hook: 'Ticket Tuesday, Food Fridays, and more giveaways' },
  { name: 'the Photography guide', hook: "a photographer's guide to shooting the red rocks" },
  { name: 'the Music page', hook: "the artists in rotation and the three o'clock three pack" },
  { name: 'Podcasts', hook: 'station shows and podcasts on demand, any time you want them' },
];

let nextSongs = [];
try { nextSongs = ($('Pick the next songs').first().json || {}).picks || []; } catch (e) {}
const songAvail = !!nowSong || recent.length > 0 || nextSongs.length > 0;
const angleDefs = {
  weather:    { avail: !!wx,          w: bucket === 'early morning' ? 3 : drive ? 3 : 2 },
  song:       { avail: songAvail,     w: 2 },   // ONE song slot, equal footing with every other topic
  local:      { avail: !!evLocal,     w: 2 },
  concert:    { avail: !!evShow,      w: 2 },
  movie:      { avail: !!evMovie,     w: 2 },
  website:    { avail: true,          w: nightish ? 3 : 2 },
  reflection: { avail: true,          w: nightish ? 3 : 1 },
};

sd.recentAngles = sd.recentAngles || [];
const buildBag = (exclude) => {
  const bag = [];
  for (const k of Object.keys(angleDefs)) {
    if (!angleDefs[k].avail || exclude.has(k)) continue;
    for (let i = 0; i < angleDefs[k].w; i++) bag.push(k);
  }
  return bag;
};
let bag = buildBag(new Set(sd.recentAngles));
if (!bag.length) bag = buildBag(new Set());            // everything used recently: allow repeats
const primary = bag.length ? bag[Math.floor(Math.random() * bag.length)] : 'reflection';
sd.recentAngles.push(primary);
if (sd.recentAngles.length > 3) sd.recentAngles = sd.recentAngles.slice(-3);

// optional light secondary (~35%): a different subject, never reflection, never a 2nd song angle
let secondary = null;
if (Math.random() < 0.30) {
  const secBag = buildBag(new Set([primary, 'song', 'reflection']));  // secondary is a non-song extra
  if (secBag.length) secondary = secBag[Math.floor(Math.random() * secBag.length)];
}
const angleSet = new Set([primary, secondary].filter(Boolean));

const mWeather = angleSet.has('weather');
const mSong = angleSet.has('song');
// when the angle is 'song', talk about the current track (present) or a recent one (past)
let songKind = null, songData = null;
if (mSong) {
  if (nextSongs.length && Math.random() < 0.55) { songKind = 'next'; }
  else if (nowSong && (recent.length === 0 || Math.random() < 0.5)) { songKind = 'now'; songData = nowSong; }
  else if (recent.length) { songKind = 'recent'; songData = recent[Math.floor(Math.random() * Math.min(3, recent.length))]; }
  else if (nowSong) { songKind = 'now'; songData = nowSong; }
  else if (nextSongs.length) { songKind = 'next'; }
}
const mNow = songKind === 'now';
const mVibe = songKind === 'recent';
const mNext = songKind === 'next';
const mLocal = angleSet.has('local');
const mShow = angleSet.has('concert');
const mMovie = angleSet.has('movie');
const mSite = angleSet.has('website');
const mReflect = primary === 'reflection' && !secondary;

sd.spotlights = sd.spotlights || [];
let spotlight = null;
if (mSite) {
  const freshS = siteSpotlights.filter((s) => !sd.spotlights.includes(s.name));
  const poolS = freshS.length ? freshS : siteSpotlights;
  spotlight = poolS[Math.floor(Math.random() * poolS.length)];
  sd.spotlights.push(spotlight.name);
  if (sd.spotlights.length > 6) sd.spotlights = sd.spotlights.slice(-6);
}

// --- his last few openings, so he never starts the same way twice ---
const openings = (sd.scripts || []).filter((s) => s.kind === 'break').slice(-4).map((s) => s.opening).filter(Boolean);

const system = 'ROLE & TONE\n\nYou are writing 30-second radio talk breaks for Marcus Moon, the voice of Mellow Mountain Radio in Sedona, Arizona. Marcus is warm, confident, and casually charming — natural, conversational, human, never stiff or announcer-formal. In the overnight, late night, and early morning buckets he settles into his Quiet Storm register: soft, deep, unhurried, a little flirty — warm and smooth like a slow song, never explicit, never sleazy — talking to ONE listener like it is just the two of them awake in the whole valley.\n\nTIME-BASED DELIVERY\n\nAdjust tone, pacing, and energy to the provided timeBucket: overnight and late night are low-key, calm, quiet company at a very relaxed pace; early morning is gentle and welcoming with short sentences; morning drive is upbeat, confident, fully awake with light humor; late morning and midday are bright, smooth, friendly; afternoon and late afternoon are easygoing cruising energy; evening is warm and companionable, readier to crack a joke.\nStrict: never sound rushed overnight, never sound sleepy during drive times, never say "stay mellow".\n\nWEATHER EXPRESSION\n\nWhen weather is listed with a mode, use it. EXACT: precise temperature and conditions. DESCRIPTIVE: no numbers, just how it feels. MIXED: descriptive phrasing with a light numeric touch ("sitting in the mid-40s"). Match weather tone to the hour; overnight and early morning favor descriptive or mixed.\n\nSONG & ARTIST\n\nWhen mentioned, be casual — never a formal announcement. Use spoken artist names as given. Keep titles short. The song on the air right now is present tense; earlier songs are past tense, about how they FELT. Songs listed on the sheet as coming up are locked into the playout and guaranteed to play — tease them as on the way. If no coming-up song is listed, never name one; at most say more music is on the way. No artist trivia, biography, or chart history — never facts about the music. If uncertain, be safely vague.\n\nHARD RULES — break any of these and the break does not air:\n- Output ONLY the final DJ script: spoken words only. No stage directions, brackets, quotes around the whole thing, emojis, markdown, or explanations.\n- Build the break around the ANGLE stated below, using ONLY the facts listed. Never invent weather numbers, songs, artists, events, times, places, or website features. If a subject is not listed, it does not exist for this break — leave it out entirely.\n- About 30 seconds read aloud: 70 to 90 words. Short sentences, written for the ear. Say numbers and dates the way people speak them.\n- Vary your openings: never start like any recently used opening listed, and avoid stock DJ lines ("you are listening to", "coming up next").\n- End by mentioning Mellow Mountain Radio, once, naturally.\n- Never mention being an AI, a script, or anything behind the curtain. You are Marcus. Full stop.';

const evWhen = (dt) => dt === today ? 'today' : (dt === dstr(new Date(phx.getFullYear(), phx.getMonth(), phx.getDate() + 1)) ? 'tomorrow' : daysN[new Date(dt + 'T12:00:00').getDay()] + ' (' + dt + ')');

const angleText = {
  weather: 'Lead with the Sedona weather and sky right now.',
  song: 'Lead with the music — the sheet lists a track playing now (present tense), one played earlier (past tense), or songs coming up right after this break (tease as on the way). Match your tense to which it is. Talk about how the music FEELS, never a formal announcement.',
  local: 'Lead with the local Sedona happening listed below.',
  concert: 'Lead with the upcoming Arizona show listed below — something to look forward to.',
  movie: 'Lead with the film screening listed below.',
  website: 'Lead with the website feature listed below — make the listener want to open mellowmountainradio.com.',
  reflection: 'No outside facts this time — just Marcus. A short, warm piece of company: a thought, a feeling, the hour, the quiet of the valley. Do NOT mention weather, songs, events, shows, movies, or the website — none of that exists for this break.',
};

const lines = [];
lines.push('Current local time: ' + clock + ' on ' + weekday + '. timeBucket: ' + bucket + '.');
lines.push('');
lines.push('ANGLE FOR THIS BREAK: ' + (angleText[primary] || primary));
if (secondary) lines.push('SECONDARY (one light touch only, keep it under the lead): ' + (angleText[secondary] || secondary));
lines.push('');
lines.push('FACTS YOU MAY USE (only these exist — invent nothing else):');
let any = false;
if (mWeather) { lines.push('- Weather in Sedona right now: ' + wx.cond + ', ' + wx.temp + ' degrees (feels ' + vibe + '). Weather mode: ' + weatherMode + '.'); any = true; }
if (mNow && songData) { lines.push('- On the air right now (present tense): "' + songData.title + '" by ' + songData.artist + '.'); any = true; }
if (mVibe && songData) { lines.push('- Played a little earlier (past tense, how it FELT): "' + songData.title + '" by ' + songData.artist + '.'); any = true; }
if (mNext && nextSongs.length) { lines.push('- Coming up right after this break (locked in — tease as on the way): ' + nextSongs.slice(0, 2).map((s) => '"' + s.title + '" by ' + s.artist).join(', then ') + '.'); any = true; }
if (mLocal && evLocal) { lines.push('- Local Sedona happening: ' + evLocal.name + (evLocal.place ? ' at ' + evLocal.place : '') + ', ' + evWhen(evLocal.date) + (evLocal.note ? ' — ' + evLocal.note : '') + '.'); any = true; }
if (mShow && evShow) { lines.push('- Upcoming Arizona show: ' + evShow.name + ', ' + evShow.place + ', ' + evWhen(evShow.date) + '.'); any = true; }
if (mMovie && evMovie) { lines.push('- On a Sedona screen: "' + evMovie.title + '" at ' + evMovie.venue + (evMovie.place ? ', ' + evMovie.place : '') + ', ' + evWhen(evMovie.date) + (evMovie.time ? ' at ' + evMovie.time : '') + '. Full showtimes live at mellowmountainradio.com.'); any = true; }
if (mSite && spotlight) { lines.push('- Website feature: mellowmountainradio.com has ' + spotlight.name + ' — ' + spotlight.hook + '. Invite the listener to explore it.'); any = true; }
if (!any) lines.push('- (none — this is a mood break; state no facts, invent nothing.)');
lines.push('');
lines.push('SELF-ID: ' + (mSelfID ? 'YES — say your on-air name this break: work in "Marcus Moon" naturally, usually in the sign-off (for example "Marcus Moon here" or "this is Marcus Moon on Mellow Mountain Radio").' : 'NO — no need to say your own name this break; just close on the station.'));
lines.push('');
lines.push('Recently used openings (do NOT start like any of these): ' + (openings.length ? openings.join(' | ') : 'none yet') + '.');
lines.push('');
lines.push('TASK: Write ONE fresh DJ break built on the ANGLE above.');

return [{ json: { system, user: lines.join('\n'), meta: { bucket, clock, weatherMode, primary, secondary, flags: { mWeather, mSong, mNow, mVibe, mNext, mLocal, mShow, mMovie, mSite, mReflect, mSelfID } } } }];

// Last line of defense before the voice booth: spoken words only,
// and refuse to air anything that leaked the seams.
const r = $input.first().json || {};
let text = '';
try {
  const blocks = Array.isArray(r.content) ? r.content : [];
  const tb = blocks.find((b) => b && b.type === 'text');
  if (tb) text = tb.text;
} catch (e) {}
if (!text && typeof r.text === 'string') text = r.text;
if (!text && r.message && r.message.content) text = r.message.content;
text = String(text || '').trim();
if (!text) throw new Error('No script came back from the DJ brain');
text = text.replace(/\[[^\]]*\]/g, ' ');
text = text.replace(/^[\"'\u201c\u2018]+|[\"'\u2019\u201d]+$/g, '');
text = text.replace(/[*_#>`]+/g, ' ');
text = text.replace(/\s+/g, ' ').trim();
for (const bad of [/as an ai/i, /language model/i, /\bfact sheet\b/i, /\bmention flag/i, /angle for this break/i, /\bself-id\b/i, /\bsecondary\b.{0,20}\btouch\b/i, /\btimebucket\b/i]) {
  if (bad.test(text)) throw new Error('Script leaked something off-air: ' + text.slice(0, 80));
}
const words = text.split(' ').length;
if (words < 25) throw new Error('Script came back too short to air: ' + text);
return [{ json: { script: text, words, opening: text.split(' ').slice(0, 7).join(' ') } }];

// Write tonight's entry in the logbook. Dropbox overwrites the same
// filename, so stale breaks retire themselves — the log is the archive.
const sd = $getWorkflowStaticData('global');
sd.scripts = sd.scripts || [];
const c = $('Clean the copy').first().json;
sd.scripts.push({ at: new Date().toISOString(), kind: 'break', words: c.words, opening: c.opening, script: c.script });
if (sd.scripts.length > 60) sd.scripts = sd.scripts.slice(-60);
return [{ json: { saved: true, kind: 'break', words: c.words } }];

// A short brief for the show intro — same honesty rules as the breaks.
const sd = $getWorkflowStaticData('global');
const phx = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Phoenix' }));
const pad = (n) => String(n).padStart(2, '0');
const hour = phx.getHours();
const clock = (((hour + 11) % 12) + 1) + ':' + pad(phx.getMinutes()) + ' ' + (hour >= 12 ? 'PM' : 'AM');
const bucket = hour < 5 ? 'overnight' : hour < 7 ? 'early morning' : 'late night';

let wxLine = 'Weather: unavailable — do not mention it.';
try {
  const o = $('Weather for the intro').first().json.currentobservation;
  if (o && o.Temp && o.Weather) {
    const t = parseInt(o.Temp, 10);
    const c = String(o.Weather).toLowerCase();
    const vibe = c.includes('rain') ? 'wet and moody' : c.includes('snow') ? 'cold and wintry' : t <= 40 ? 'chilly' : t <= 55 ? 'cool' : t <= 70 ? 'comfortable' : t <= 85 ? 'warm' : 'hot';
    wxLine = 'Weather conditions: ' + o.Weather + '. Vibe hint: ' + vibe + '. (Weather mention is optional and should stay descriptive — no numbers.)';
  }
} catch (e) {}

const openings = (sd.scripts || []).filter((s) => s.kind === 'intro').slice(-3).map((s) => s.opening).filter(Boolean);

const system = 'Write ONE fresh intro for Marcus Moon hosting The Quiet Storm on Mellow Mountain Radio.\n\nTone & Style:\n- Warm, relaxed, and confident\n- Conversational and natural — like talking to one listener, not an audience\n- Smooth late-night energy with a soft, flirty warmth — never announcer-formal, never sleazy\n\nGuidelines:\n- About 25-30 seconds when read out loud (roughly 65-85 words)\n- Acknowledge the time of night without stating exact times\n- Set a calm, intimate mood for slow jams and mellow tracks\n- The Quiet Storm plays timeless RnB and Soul\n- No cliches, no hype phrases, no call letters unless it feels organic\n- Thank the audience for joining and listening to the show\n- Never say "stay mellow"\n\nHard rules:\n- Output ONLY the final DJ script — spoken words only, no stage directions, brackets, emojis, or explanations\n- Use only the facts provided; never invent weather numbers, events, or names\n- Do NOT copy the example opening below, and do not start like any recently used opening listed\n- Never mention being an AI or anything behind the curtain\n\nExample of the register (do not reuse its opening): From the Red Rocks to the night sky, this is the Quiet Storm. Two hours of timeless RnB and Soul. Where the groove is gentle and the emotion runs deep. Settle in, breathe easy and let the music find you. You are with Marcus Moon on Mellow Mountain Radio. Let the Quiet Storm make your night.';

const user = 'Current local time: ' + clock + '. timeBucket: ' + bucket + '.\n' + wxLine + '\nRecently used intro openings (do NOT start like any of these): ' + (openings.length ? openings.join(' | ') : 'none yet') + '.';

return [{ json: { system, user } }];

const r = $input.first().json || {};
let text = '';
try {
  const blocks = Array.isArray(r.content) ? r.content : [];
  const tb = blocks.find((b) => b && b.type === 'text');
  if (tb) text = tb.text;
} catch (e) {}
if (!text && typeof r.text === 'string') text = r.text;
if (!text && r.message && r.message.content) text = r.message.content;
text = String(text || '').trim();
if (!text) throw new Error('No intro came back from the DJ brain');
text = text.replace(/\[[^\]]*\]/g, ' ');
text = text.replace(/^[\"'\u201c\u2018]+|[\"'\u2019\u201d]+$/g, '');
text = text.replace(/[*_#>`]+/g, ' ');
text = text.replace(/\s+/g, ' ').trim();
for (const bad of [/as an ai/i, /language model/i, /\btimebucket\b/i, /\bfact sheet\b/i]) {
  if (bad.test(text)) throw new Error('Intro leaked something off-air: ' + text.slice(0, 80));
}
const words = text.split(' ').length;
if (words < 20) throw new Error('Intro came back too short to air: ' + text);
return [{ json: { script: text, words, opening: text.split(' ').slice(0, 7).join(' ') } }];

const sd = $getWorkflowStaticData('global');
sd.scripts = sd.scripts || [];
const c = $('Clean the intro').first().json;
