// The events board: a human writes it, Marcus only ever reads it.
// ?k=moon-2026&do=add&date=YYYY-MM-DD&name=...&place=...&note=...
// ?k=moon-2026&do=remove&i=0        ?k=moon-2026 (list)
const q = $input.first().json.query || {};
const sd = $getWorkflowStaticData('global');
sd.events = sd.events || [];
if (q.k !== 'moon-2026') return [{ json: { ok: false, why: 'bad key' } }];
const act = q.do || 'list';
if (act === 'add') {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(q.date || '') || !q.name) {
    return [{ json: { ok: false, why: 'need date=YYYY-MM-DD and name=' } }];
  }
  sd.events.push({ date: q.date, name: String(q.name).slice(0, 120), place: String(q.place || '').slice(0, 80), note: String(q.note || '').slice(0, 200) });
  sd.events.sort((a, b) => (a.date < b.date ? -1 : 1));
}
if (act === 'remove') {
  const i = parseInt(q.i, 10);
  if (!isNaN(i) && i >= 0 && i < sd.events.length) sd.events.splice(i, 1);
}
const phx = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Phoenix' }));
const pad = (n) => String(n).padStart(2, '0');
const today = phx.getFullYear() + '-' + pad(phx.getMonth() + 1) + '-' + pad(phx.getDate());
sd.events = sd.events.filter((e) => e.date >= today);
return [{ json: { ok: true, events: sd.events.map((e, i) => ({ i, ...e })) } }];

// Read the last ten scripts — what Marcus said and when he said it.
const q = $input.first().json.query || {};
const sd = $getWorkflowStaticData('global');
if (q.k !== 'moon-2026') return [{ json: { ok: false, why: 'bad key' } }];
const scripts = (sd.scripts || []).slice(-10).reverse();
return [{ json: { ok: true, scripts, events: sd.events || [] } }];

// Pick tonight's next songs from the MegaSeg library — the workflow is the
// music director now, so Marcus can tease coming-up songs with certainty.
const sd = $getWorkflowStaticData('global');

let raw = '';
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  raw = buf.toString('utf8');
} catch (e) {}

const cleanT = (t) => String(t || '').split(/\s+-\s+/)[0].replace(/\([^)]*\)/g, '').replace(/\s+/g, ' ').trim().toLowerCase();

// recently aired titles from AzuraCast (history + now playing)
const recentTitles = new Set();
try {
  const np = $('Ask the airwaves').first().json || {};
  const nowT = np.now_playing && np.now_playing.song && np.now_playing.song.title;
  if (nowT) recentTitles.add(cleanT(nowT));
  for (const r of (np.song_history || []).slice(0, 15)) {
    if (r && r.song && r.song.title) recentTitles.add(cleanT(r.song.title));
  }
} catch (e) {}

sd.scheduledSongs = sd.scheduledSongs || [];
const recentIds = new Set(sd.scheduledSongs);

// parse MegaSeg Database records (numbered-field format, records split by "99* ----")
const pool = [];
if (raw.startsWith('D**')) {
  for (const rec of raw.split('99* ----').slice(1)) {
    const f = {};
    for (const line of rec.split('\n')) {
      const m = line.match(/^(\d\d)\]\s?(.*)$/);
      if (m) f[m[1]] = m[2].replace(/\r$/, '');
    }
    const cats = String(f['06'] || '').split('/');
    if (!cats.some((c) => c === '+Quiet Storm' || c === '+Quiet Storm 10')) continue;
    if (!f['01'] || !f['49'] || !f['45']) continue;
    pool.push(f);
  }
}

// convert mm:ss.xx (or hh:mm:ss.xx) to seconds
const toSecs = (t) => {
  const p = String(t || '').split(':').map(Number);
  if (p.some(isNaN) || !p.length) return 0;
  return p.reduce((a, b) => a * 60 + b, 0);
};

// prefer songs neither aired recently nor scheduled by us recently
let candidates = pool.filter((f) => !recentTitles.has(cleanT(f['01'])) && !recentIds.has(f['45']));
if (candidates.length < 3) candidates = pool.filter((f) => !recentIds.has(f['45']));
if (candidates.length < 3) candidates = pool.slice();

const picks = [];
const bag = candidates.slice();
while (picks.length < 3 && bag.length) {
  picks.push(bag.splice(Math.floor(Math.random() * bag.length), 1)[0]);
}

// build exact MegaSeg playlist TSV rows (25 columns, matching MegaSeg's own export)
const rows = picks.map((f) => {
  const cols = new Array(25).fill('');
  cols[0] = f['01'];                          // Name
  cols[1] = f['02'] || '';                    // Artist
  cols[3] = f['09'] || '';                    // Album
  cols[4] = String(f['06'] || '').split('/')[0]; // Genre (first category)
  cols[6] = toSecs(f['05']).toFixed(2);       // Time in seconds
  cols[11] = f['10'] || '';                   // Year
  cols[20] = f['14'] || '0';                  // Plays
  cols[21] = f['15'] || '';                   // Last Played
  cols[22] = '0';                             // My Rating
  cols[23] = f['49'];                         // Location
  cols[24] = f['45'];                         // UniqueID
  return cols.join('\t');
});

// remember what we scheduled so nights don't repeat
for (const f of picks) sd.scheduledSongs.push(f['45']);
if (sd.scheduledSongs.length > 24) sd.scheduledSongs = sd.scheduledSongs.slice(-24);

return [{ json: {
  poolSize: pool.length,
  picks: picks.map((f) => ({ title: f['01'], artist: f['02'] || '' })),
  rows,
} }];

// Rebuild the "Quiet Storm DJ VO" MegaSeg playlist: the fresh VO, bed music,
