const HEADER = 'Name\tArtist\tComposer\tAlbum\tGenre\tSize\tTime\tDisc Number\tDisc Count\tTrack Number\tTrack Count\tYear\tDate Modified\tDate Added\tBit Rate\tSample Rate\tVolume Adjustment\tKind\tEqualizer\tComments\tPlays\tLast Played\tMy Rating\tLocation\tUniqueID';
const VO_ROW = 'Quiet Storm Weekdays 4a-6a\tMarcus Moon\t\t\t+Quiet Storm Liners 10\t\t6.900000e-6\t\t\t\t\t\t\t12/9/25 4:53 PM\t\t\t\t\t\t\t0\t\t0\tMacintosh HD:Users:mellowmountainradio:MellowMountainRadio Dropbox:Charles Helstein:Quite Storm Show:qsvo.mp3\t3848144018-18910';

let rows = [];
try { rows = $('Pick the next songs').first().json.rows || []; } catch (e) {}

